{"command": "mkdir -p /tmp/goexp && cd /tmp/goexp && cat > main.go <<'EOF'
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"
)

func try(s string) {
	dec := json.NewDecoder(strings.NewReader(s))
	var v interface{}
	err := dec.Decode(&v)
	off := dec.InputOffset()
	consumed := ""
	if int(off) <= len(s) {
		consumed = s[:off]
	}
	fmt.Printf("IN=%q ERR=%v V=%v OFF=%d CONSUMED=%q REST=%q\n", s, err, v, off, consumed, s[off:])
}

func main() {
	for _, s := range []string{" { ;;", " {x;", " { };", " {} 1;", " \"x\" {};", " 1 {};", " {}", " {}", " {}", " 1 2;", " x y;", " {", " {x", " ;", " 1;"} {
		try(s)
	}
	fmt.Println("--- Token based")
	for _, s := range []string{" { ;;", " {x;", " { };", " {} 1;", " 1 2;"} {
		dec := json.NewDecoder(strings.NewReader(s))
		var toks []string
		for i := 0; i < 5; i++ {
			t, err := dec.Token()
			if err != nil {
				toks = append(toks, fmt.Sprintf("ERR:%v@%d", err, dec.InputOffset()))
				break
			}
			toks = append(toks, fmt.Sprintf("%v@%d", t, dec.InputOffset()))
		}
		fmt.Printf("IN=%q TOKS=%v\n", s, toks)
	}
	fmt.Println("--- Unmarshal")
	for _, s := range []string{"{ ;;", "{x;", "{ };", "{} 1;", "1 2;", "x y;", "{"} {
		var v interface{}
		err := json.Unmarshal([]byte(s), &v)
		fmt.Printf("IN=%q ERR=%v V=%v\n", s, err, v)
	}
	_ = bytes.MinRead
}
EOF
go run main.go"}

