package main

import (
	"encoding/json"
	"fmt"
	"strings"
)

func tokens(s string) {
	dec := json.NewDecoder(strings.NewReader(s))
	dec.UseNumber()
	var toks []string
	for i := 0; i < 8; i++ {
		t, err := dec.Token()
		if err != nil {
			toks = append(toks, fmt.Sprintf("ERR(%v)", err))
			break
		}
		toks = append(toks, fmt.Sprint(t))
	}
	fmt.Printf("%-22q %v\n", s, toks)
}

