	for _, s := range []string{"{\"a\":}", "{a:1}", "{\"a\" 1}", "[1,]", "[1 2]", "{\"a\":1,}", "{\"a\":1 \"b\":2}", "{\"a\":01}", "{\"a\":1e}"} {
		tokens(s)
	}
}
EOF
