package main

import (
	"bytes"
	"encoding/json"
	"strconv"
	"strings"
	"unicode"
)

// reservedWords is the set of words that may not be used as a bare (unquoted)
// JavaScript identifier in gron's output.  The list was determined by probing
// the original binary with a large number of candidate keys.
var reservedWords = map[string]bool{
	"break":      true,
	"case":       true,
	"catch":      true,
	"char":       true,
	"class":      true,
	"const":      true,
	"continue":   true,
	"debugger":   true,
	"default":    true,
	"delete":     true,
	"do":         true,
	"else":       true,
	"export":     true,
	"extends":    true,
	"false":      true,
	"finally":    true,
	"for":        true,
	"function":   true,
	"if":         true,
	"import":     true,
	"in":         true,
	"instanceof": true,
	"new":        true,
	"null":       true,
	"return":     true,
	"super":      true,
	"switch":     true,
	"this":       true,
	"throw":      true,
	"try":        true,
	"typeof":     true,
	"var":        true,
	"void":       true,
	"while":      true,
	"with":       true,
	"true":       true,
	"yield":      true,
}

// isBareKey reports whether key can be written as a bare (unquoted) JavaScript
// identifier.
func isBareKey(key string) bool {
	if key == "" {
		return false
	}
	for i, r := range key {
		switch {
		case i == 0:
			if !unicode.IsLetter(r) && r != '_' && r != '$' {
				return false
			}
		default:
			if !unicode.IsLetter(r) && !unicode.IsDigit(r) && r != '_' && r != '$' {
				return false
			}
		}
	}
	if reservedWords[key] {
		return false
	}
	return true
}

// jsonString returns the JSON encoding of s.  HTML escaping is disabled to
// match gron's output (<, > and & are emitted verbatim).
func jsonString(s string) string {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(s); err != nil {
		return ""
	}
	return strings.TrimSuffix(buf.String(), "\n")
}

// encodeValue renders a decoded JSON value the way gron does.  Numbers are
// emitted exactly as they appeared in the input.
func encodeValue(v interface{}) string {
	switch t := v.(type) {
	case nil:
		return "null"
	case bool:
		if t {
			return "true"
		}
		return "false"
	case json.Number:
		return t.String()
	case string:
		return jsonString(t)
	}
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(v); err != nil {
		return ""
	}
	return strings.TrimSuffix(buf.String(), "\n")
}

// jsonNumberString converts a decoded float64 back into gron's number form.
func jsonNumberString(f float64) string {
	return strconv.FormatFloat(f, 'g', -1, 64)
}
