package main

// ANSI escape sequences used by gron.  The sequences were observed from the
// original binary and are reproduced verbatim.
const (
	colReset = "\x1b[0m"

	// Keys (path elements) are rendered in bold blue.
	colKey = "\x1b[34;1m"
	// The reset used after a bold blue key keeps "bold off" in the sequence.
	colKeyReset = "\x1b[0;22m"

	// Containers ({} and []) and the square brackets around array indices.
	colContainer = "\x1b[35m"

	// Numbers.
	colNumber = "\x1b[31m"

	// Strings.
	colString = "\x1b[33m"

	// Booleans and null.
	colBool = "\x1b[36m"

	// String quotes in ungronned output are green, the contents yellow.
	colQuote = "\x1b[32m"

	// Bold punctuation (: and ,) in ungronned output.
	colBold = "\x1b[1m"
	// The reset used after bold punctuation.
	colBoldReset = "\x1b[22m"
)

// colour wraps a string in the given escape sequences when colour is enabled.
func colour(on bool, pre, post, s string) string {
	if !on {
		return s
	}
	return pre + s + post
}
