package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"strconv"
	"strings"
)

var (
	errInvalidQuotedKey = errors.New("invalid quoted key")
)

func isSpaceByte(c byte) bool {
	switch c {
	case ' ', '\t', '\n', '\r', '\v', '\f':
		return true
	}
	return false
}

func isIdentStartByte(c byte) bool {
	return c == '_' || c == '$' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c >= 0x80
}

func isIdentContByte(c byte) bool {
	return isIdentStartByte(c) || (c >= '0' && c <= '9')
}

func isDigitByte(c byte) bool {
	return c >= '0' && c <= '9'
}

// readIdent returns the index just past the identifier starting at i.
func readIdent(line string, i int) int {
	j := i
	for j < len(line) && isIdentContByte(line[j]) {
		// multi-byte runes are allowed as long as they are letters or digits
		if line[j] >= 0x80 {
			r, size := utf8DecodeRuneInString(line[j:])
			if !isIdentRune(r, j == i) {
				break
			}
			j += size
			continue
		}
		j++
	}
	return j
