	d := json.NewDecoder(strings.NewReader(value))
	d.UseNumber()
	if err := d.Decode(&v); err != nil {
		return st, fmt.Errorf("invalid value `%s`", strings.TrimSuffix(value, ";"))
	}
	return st, nil
}

// key resolves a path element to the object key it denotes.
func (e pathElement) keyOf() (string, error) {
	if e.kind != elemQuotedKey {
		return e.key, nil
	}
	var s string
	d := json.NewDecoder(strings.NewReader(e.raw))
	if err := d.Decode(&s); err != nil {
		return "", fmt.Errorf("invalid quoted key `%s`", e.raw)
	}
	return s, nil
}

// buildStatements merges the statements into a single JSON value.
func buildStatements(sts statements) (interface{}, error) {
	var tree interface{}
	for _, st := range sts {
		v, err := st.decodedValue()
		if err != nil {
			return nil, err
		}
		// resolve the keys in the path
		path := make([]pathElement, 0, len(st.path))
		for _, e := range st.path {
			k, err := e.keyOf()
			if err != nil {
				return nil, err
			}
			el := e
			el.key = k
			path = append(path, el)
		}
		tree, err = mergeValue(tree, path, v)
		if err != nil {
			return nil, err
		}
	}
	return unwrapRoot(tree), nil
}

// ungronErrorf wraps an error with the statement that caused it.
func ungronErrorf(st *statement, err error) error {
	return fmt.Errorf("ungron failed for `%s`: %v", st.String(), err)
}
