}

func isIdentContByte(c byte) bool {
	return isIdentStartByte(c) || (c >= '0' && c <= '9')
}

func isDigitByte(c byte) bool {
	return c >= '0' && c <= '9'
}

// readIdent returns the index just past the identifier starting at i.
func readIdent(line string, i int) int {
	j := i
	for j < len(line) && isIdentContByte(line[j]) {
		// multi-byte runes are allowed as long as they are letters or digits
		if line[j] >= 0x80 {
			r, size := utf8DecodeRuneInString(line[j:])
			if !isIdentRune(r, j == i) {
				break
			}
			j += size
			continue
		}
		j++
	}
	return j
}

// scanQuoted scans a double quoted JSON string starting at the opening quote.
// It returns the index just past the closing quote, or -1 when unterminated.
func scanQuoted(line string, i int) int {
	j := i + 1
	for j < len(line) {
		switch line[j] {
		case '\\':
			j++
			if j < len(line) {
				j++
			}
		case '"':
			return j + 1
		default:
			j++
		}
	}
	return -1
}

// parseStatement parses a single line into a statement.  It returns
// (nil, nil) when the line does not even look like a statement, and
// (nil, err) when it fails in a way that gron silently ignores.
func parseStatement(line string) (*statement, error) {
	if line == "" || line[0] == ' ' {
		return nil, nil
	}
	line = strings.TrimRight(line, " ")
	if line == "" {
		return nil, nil
	}

	i := 0
	var path []pathElement
	haveRoot := false
	if isIdentStartByte(line[i]) {
		j := readIdent(line, i)
		path = append(path, pathElement{kind: elemBareKey, key: line[i:j], raw: line[i:j]})
		i = j
		haveRoot = true
	}

	for i < len(line) {
		c := line[i]
		switch {
		case c == '.':
			i++
			if i < len(line) && isIdentStartByte(line[i]) {
				j := readIdent(line, i)
				path = append(path, pathElement{kind: elemBareKey, key: line[i:j], raw: line[i:j]})
				i = j
				continue
			}
			return badStatement(line, i)
		case c == '[':
			i++
			if i >= len(line) {
				return badStatement(line, i)
			}
			if line[i] == '"' {
				j := scanQuoted(line, i)
				if j < 0 {
					return badStatement(line, len(line))
				}
				if j >= len(line) || line[j] != ']' {
					return badStatement(line, j)
				}
				path = append(path, pathElement{
					kind: elemQuotedKey,
					raw:  line[i:j],
				})
				i = j + 1
				continue
			}
			if isDigitByte(line[i]) {
				k := i
				for k < len(line) && isDigitByte(line[k]) {
					k++
				}
				if k >= len(line) || line[k] != ']' {
					return badStatement(line, k)
				}
				idx, err := strconv.Atoi(line[i:k])
				if err != nil {
					return badStatement(line, k)
				}
				path = append(path, pathElement{
					kind:  elemIndex,
					index: idx,
					raw:   line[i : k+1],
				})
				i = k + 1
				continue
			}
			return badStatement(line, i)
		case isIdentStartByte(c):
			j := readIdent(line, i)
			path = append(path, pathElement{kind: elemBareKey, key: line[i:j], raw: line[i:j]})
			i = j
			continue
		}
		break
	}

	rawPath := pathText(path)

	// A statement made up of a single root identifier and nothing else is not
	// a statement at all.
	onlyRoot := haveRoot && len(path) == 1

	if i >= len(line) {
		if onlyRoot {
			return nil, errInvalidStatement
		}
		st := &statement{path: path, raw: rawPath, value: "", hasEq: false}
		return st, errNoValue
	}
	c := line[i]
	switch {
	case c == '=':
		return parseValue(line, i+1, path, rawPath)
	case c == ' ':
		j := i
		for j < len(line) && line[j] == ' ' {
			j++
		}
		if j < len(line) && line[j] == '=' {
			return parseValue(line, j+1, path, rawPath)
		}
		if onlyRoot {
			return nil, errInvalidStatement
		}
		st := &statement{path: path, raw: rawPath, value: "", hasEq: false}
		return st, errNoValue
	}
	st := &statement{path: path, raw: rawPath, value: "", hasEq: false}
	return st, errInvalidStatement
}

// badStatement reports a malformed statement.  The statement is still returned
// so that gron can render it in the error message.
func badStatement(line string, i int) (*statement, error) {
	st := &statement{path: nil, raw: line[:i], value: "", hasEq: false}
	return st, errInvalidStatement
}

// pathText renders a parsed path back to text, using the raw element text.
func pathText(path []pathElement) string {
	var sb strings.Builder
	for i, e := range path {
		switch {
		case i == 0:
			sb.WriteString(e.raw)
		case e.kind == elemBareKey:
			sb.WriteString("." + e.raw)
		default:
			sb.WriteString(e.raw)
		}
	}
	return sb.String()
}

// parseValue parses the value part of a statement, starting at index i.
func parseValue(line string, i int, path []pathElement, rawPath string) (*statement, error) {
	j := i
	for j < len(line) && isSpaceByte(line[j]) {
		j++
	}
	if j >= len(line) {
		st := &statement{path: path, raw: rawPath, value: "", hasEq: true}
		return st, errNoValue
	}
	c := line[j]
	switch {
	case c == '"':
		k := scanQuoted(line, j)
		if k < 0 {
			k = len(line)
		}
		value := line[j:k]
		m := k
		for m < len(line) && isSpaceByte(line[m]) {
			m++
		}
		if m >= len(line) || line[m] != ';' {
			st := &statement{path: path, raw: rawPath, value: value, hasEq: true}
			return st, errNoValue
		}
		return &statement{path: path, raw: rawPath, value: value, hasEq: true}, nil
	case c == '{' || c == '[':
		close := byte('}')
		if c == '[' {
			close = ']'
		}
		if j+1 < len(line) && line[j+1] == close {
			value := line[j : j+2]
			m := j + 2
			for m < len(line) && isSpaceByte(line[m]) {
				m++
			}
			if m >= len(line) || line[m] != ';' {
				st := &statement{path: path, raw: rawPath, value: value, hasEq: true}
				return st, errNoValue
			}
			return &statement{path: path, raw: rawPath, value: value, hasEq: true}, nil
		}
		m := j + 1
		for m < len(line) && isSpaceByte(line[m]) {
			m++
		}
		if m < len(line) && line[m] == ';' {
			value := strings.TrimSpace(line[j:m]) + ";"
			st := &statement{path: path, raw: rawPath, value: value, hasEq: true}
			return st, fmt.Errorf("invalid value `%s`", strings.TrimSuffix(value, ";"))
		}
		st := &statement{path: path, raw: rawPath, value: line[j : j+1], hasEq: true}
		return st, errNoValue
	}
	k := strings.IndexByte(line[j:], ';')
	if k < 0 {
		st := &statement{path: path, raw: rawPath, value: line[j:], hasEq: true}
		return st, errNoValue
	}
	value := line[j : j+k+1]
	st := &statement{path: path, raw: rawPath, value: value, hasEq: true}
	var v interface{}
	d := json.NewDecoder(strings.NewReader(value))
	d.UseNumber()
	if err := d.Decode(&v); err != nil {
		return st, fmt.Errorf("invalid value `%s`", strings.TrimSuffix(value, ";"))
	}
	return st, nil
}

// key resolves a path element to the object key it denotes.
func (e pathElement) keyOf() (string, error) {
	if e.kind != elemQuotedKey {
		return e.key, nil
	}
	var s string
	d := json.NewDecoder(strings.NewReader(e.raw))
	if err := d.Decode(&s); err != nil {
		return "", fmt.Errorf("invalid quoted key `%s`", e.raw)
	}
	return s, nil
}

// buildStatements merges the statements into a single JSON value.
func buildStatements(sts statements) (interface{}, error) {
	var tree interface{}
	for _, st := range sts {
		v, err := st.decodedValue()
		if err != nil {
			return nil, err
		}
		// resolve the keys in the path
		path := make([]pathElement, 0, len(st.path))
		for _, e := range st.path {
			k, err := e.keyOf()
			if err != nil {
				return nil, err
			}
			el := e
			el.key = k
			path = append(path, el)
		}
		tree, err = mergeValue(tree, path, v)
		if err != nil {
			return nil, err
		}
	}
	return unwrapRoot(tree), nil
}

// ungronErrorf wraps an error with the statement that caused it.
func ungronErrorf(st *statement, err error) error {
	return fmt.Errorf("ungron failed for `%s`: %v", st.String(), err)
}
