	fs := flag.NewFlagSet("gron", flag.ExitOnError)
	fs.BoolVar(&opts.ungron, "u", false, "Reverse the operation (turn assignments back into JSON)")
	fs.BoolVar(&opts.ungron, "ungron", false, "Reverse the operation (turn assignments back into JSON)")
	fs.BoolVar(&opts.values, "v", false, "Print just the values of provided assignments")
	fs.BoolVar(&opts.values, "values", false, "Print just the values of provided assignments")
