import subprocess, sys, itertools, string, json

ORIG='/workspace/executable'
MINE='/tmp/gron-test'

def run(bin, args, inp=None, timeout=20):
    try:
        p = subprocess.run([bin]+args, input=inp, capture_output=True, text=True, timeout=timeout)
        return (p.stdout, p.stderr, p.returncode)
    except subprocess.TimeoutExpired:
        return ('', 'TIMEOUT', -1)

def cmp(args, inp=None, label=None):
    a = run(ORIG, args, inp)
    b = run(MINE, args, inp)
    if a != b:
        print('MISMATCH', args, repr(inp)[:120], label or '')
        if a[0]!=b[0]: print('  stdout orig:',repr(a[0])[:300]); print('  stdout mine:',repr(b[0])[:300])
        if a[1]!=b[1]: print('  stderr orig:',repr(a[1])[:300]); print('  stderr mine:',repr(b[1])[:300])
        if a[2]!=b[2]: print('  rc orig:',a[2],'mine:',b[2])
        return False
    return True

if __name__ == '__main__':
    ok=0; bad=0
    tests = json.load(open(sys.argv[1]))
    for t in tests:
        args = t.get('args', [])
        inp = t.get('inp')
        if cmp(args, inp, t.get('label')): ok+=1
        else: bad+=1
    print('ok=%d bad=%d' % (ok,bad))
