{"command": "cd /workspace/src && python3 - <<'PYEOF'
content = r'''
package main

import (
	"encoding/json"
	"errors"
	"sort"
	"strconv"
	"strings"
)

type elemKind int

const (
	elemBareKey elemKind = iota
	elemQuotedKey
	elemIndex
)

// pathElement is a single element of a statement's path.
type pathElement struct {
	kind  elemKind
	key   string
	index int
	raw   string // the element exactly as it was written, brackets included
	quote string // for quoted keys: the quoted string without the brackets
}

// statement is a single gron statement such as `json.foo.bar = "baz";`.
type statement struct {
	path   []pathElement
	raw    string      // the path as it was written (used in error messages)
	value  string      // the value as it was written ("" when unknown)
	hasEq  bool        // whether the statement contained an '=' at all
	jval   interface{} // the decoded value (json stream mode)
	isJSON bool        // whether the statement came from a json stream
}

// String renders the statement the way gron shows it in error messages.
func (s *statement) String() string {
	if !s.hasEq {
		return s.raw
	}
	if s.isJSON {
		return s.raw + " = " + s.value + ";"
	}
	return s.raw + " = " + s.value
}

// sortKey returns the string used to order path elements when sorting
// statements.  Bare keys are prefixed with a dot, quoted keys and indices with
// a bracket, which reproduces the ordering of the original binary.
func (e pathElement) sortKey() string {
	switch e.kind {
	case elemBareKey:
		return "." + e.key
	case elemQuotedKey:
		return `["` + strings.Trim(jsonString(e.key), `"`) + `"]`
	default:
		return "[" + strconv.Itoa(e.index) + "]"
	}
}

// byPath orders statements by their path, comparing element by element.
type byPath []*statement

func (a byPath) Len() int      { return len(a) }
func (a byPath) Swap(i, j int) { a[i], a[j] = a[j], a[i] }
func (a byPath) Less(i, j int) bool {
	x, y := a[i].path, a[j].path
	n := len(x)
	if len(y) < n {
		n = len(y)
	}
	for k := 0; k < n; k++ {
		if x[k].kind == elemIndex && y[k].kind == elemIndex {
			if x[k].index != y[k].index {
				return x[k].index < y[k].index
			}
			continue
		}
		xs, ys := x[k].sortKey(), y[k].sortKey()
		if xs != ys {
			return xs < ys
		}
	}
	return len(x) < len(y)
}

// render renders a single path element, optionally with colours.
func (e pathElement) render(colourise bool) string {
	switch e.kind {
	case elemBareKey:
		return colour(colourise, colKey, colKeyReset, e.key)
	case elemQuotedKey:
		q := colour(colourise, colString, colReset, jsonString(e.key))
		return colour(colourise, colContainer, colReset, "[") + q +
			colour(colourise, colContainer, colReset, "]")
	default:
		n := colour(colourise, colNumber, colReset, strconv.Itoa(e.index))
		return colour(colourise, colContainer, colReset, "[") + n +
			colour(colourise, colContainer, colReset, "]")
	}
}

// renderPath renders a whole path, optionally with colours.  The first element
// is written without any separator; subsequent bare keys are preceded by a dot.
func renderPath(path []pathElement, colourise bool) string {
	var sb strings.Builder
	for i, e := range path {
		if i > 0 && e.kind == elemBareKey {
			sb.WriteString(".")
		}
		sb.WriteString(e.render(colourise))
	}
	return sb.String()
}

// withElem returns a copy of path with e appended.
func withElem(path []pathElement, e pathElement) []pathElement {
	np := make([]pathElement, len(path)+1)
	copy(np, path)
	np[len(path)] = e
	return np
}

// withRoot returns a copy of path with e prepended.
func withRoot(path []pathElement, e pathElement) []pathElement {
	np := make([]pathElement, len(path)+1)
	np[0] = e
	copy(np[1:], path)
	return np
}

// gronPath prepends the conventional "json" root to a path.
func gronPath(path []pathElement) []pathElement {
	return withRoot(path, pathElement{kind: elemBareKey, key: "json", raw: "json"})
}

// setValue renders the value of a statement, optionally with colours.
func setValue(v string, colourise bool) string {
	switch {
	case v == "{}" || v == "[]":
		return colour(colourise, colContainer, colReset, v)
	case strings.HasPrefix(v, `"`):
		return colour(colourise, colString, colReset, v)
	case v == "null" || v == "true" || v == "false":
		return colour(colourise, colBool, colReset, v)
	default:
		return colour(colourise, colNumber, colReset, v)
	}
}

// statements is an ordered list of statements.
type statements []*statement

// keyElement builds the path element for an object key, choosing between a
// bare and a quoted representation.
func keyElement(key string) pathElement {
	if isBareKey(key) {
		return pathElement{kind: elemBareKey, key: key, raw: key}
	}
	return pathElement{kind: elemQuotedKey, key: key, raw: jsonString(key), quote: jsonString(key)}
}

// readJSONValue reads the next JSON value from dec, appending the statements
// that describe it to sts.  Statements are produced in document order.
func readJSONValue(dec *json.Decoder, path []pathElement, sts *statements) error {
	first, err := dec.Token()
	if err != nil {
		return err
	}
	return walkJSON(dec, first, path, sts)
}

// walkJSON writes statements for the value whose first token is first.
func walkJSON(dec *json.Decoder, first json.Token, path []pathElement, sts *statements) error {
	if d, ok := first.(json.Delim); ok {
		switch d {
		case '{':
			*sts = append(*sts, &statement{path: path, raw: renderPath(gronPath(path), false), value: "{}"})
			for {
				kt, err := dec.Token()
				if err != nil {
					return err
				}
				if kt == json.Delim('}') {
					return nil
				}
				key, ok := kt.(string)
				if !ok {
					return errors.New("invalid JSON layout")
				}
				vt, err := dec.Token()
				if err != nil {
					return err
				}
				if err := walkJSON(dec, vt, withElem(path, keyElement(key)), sts); err != nil {
					return err
				}
			}
		case '[':
			*sts = append(*sts, &statement{path: path, raw: renderPath(gronPath(path), false), value: "[]"})
			for i := 0; ; i++ {
				vt, err := dec.Token()
				if err != nil {
					return err
				}
				if vt == json.Delim(']') {
					return nil
				}
				el := pathElement{kind: elemIndex, index: i, raw: "[" + strconv.Itoa(i) + "]"}
				if err := walkJSON(dec, vt, withElem(path, el), sts); err != nil {
					return err
				}
			}
		}
		return nil
	}
	*sts = append(*sts, &statement{
		path:  path,
		raw:   renderPath(gronPath(path), false),
		value: encodeValue(first),
	})
	return nil
}

// sortStatements orders the statements by path unless noSort is set.
func (sts statements) sortStatements(noSort bool) {
	if noSort {
		return
	}
	sort.Stable(byPath(sts))
}

var (
	errInvalidStatement = errors.New("invalid statement")
	errNoValue          = errors.New("statement has no value")
)

// decodedValue returns the statement's value as a decoded Go value.
func (s *statement) decodedValue() (interface{}, error) {
	if s.isJSON {
		return s.jval, nil
	}
	switch s.value {
	case "{}":
		return map[string]interface{}{}, nil
	case "[]":
		return []interface{}{}, nil
	}
	var v interface{}
	d := json.NewDecoder(strings.NewReader(s.value))
	d.UseNumber()
	if err := d.Decode(&v); err != nil {
		return nil, fmt.Errorf("invalid value `%s`", strings.TrimSuffix(s.value, ";"))
	}
	return v, nil
}

// buildTree merges a list of statements into a single JSON value.
func buildTree(sts statements) (interface{}, error) {
	var tree interface{}
	for _, st := range sts {
		v, err := st.decodedValue()
		if err != nil {
			return nil, err
		}
		path := make([]pathElement, 0, len(st.path))
		for _, e := range st.path {
			k, err := elementKey(e)
			if err != nil {
				return nil, err
			}
			el := e
			el.key = k
			path = append(path, el)
		}
		tree, err = mergeValue(tree, path, v)
		if err != nil {
			return nil, err
		}
	}
	return tree, nil
}

// elementKey resolves a path element to the object key it denotes.
func elementKey(e pathElement) (string, error) {
	if e.kind != elemQuotedKey {
		return e.key, nil
	}
	var s string
	d := json.NewDecoder(strings.NewReader(e.quote))
	if err := d.Decode(&s); err != nil {
		return "", fmt.Errorf("invalid quoted key `%s`", e.quote)
	}
	return s, nil
}

// mergeValue merges value into dst at the given path.
func mergeValue(dst interface{}, path []pathElement, value interface{}) (interface{}, error) {
	if len(path) == 0 {
		if dst != nil {
			return nil, errors.New("cannot merge object with non-object")
		}
		return value, nil
	}
	e := path[0]
	if e.kind == elemIndex {
		switch t := dst.(type) {
		case map[string]interface{}:
			return nil, errors.New("cannot merge object with non-object")
		case []interface{}:
			for len(t) <= e.index {
				t = append(t, nil)
			}
			child, err := mergeValue(t[e.index], path[1:], value)
			if err != nil {
				return nil, err
			}
			t[e.index] = child
			return t, nil
		default:
			arr := make([]interface{}, e.index+1)
			child, err := mergeValue(arr[e.index], path[1:], value)
			if err != nil {
				return nil, err
			}
			arr[e.index] = child
			return arr, nil
		}
	}
	switch t := dst.(type) {
	case []interface{}:
		return nil, errors.New("cannot merge array with non-array")
	case map[string]interface{}:
		child, err := mergeValue(t[e.key], path[1:], value)
		if err != nil {
			return nil, err
		}
		t[e.key] = child
		return t, nil
	default:
		obj := map[string]interface{}{}
		child, err := mergeValue(nil, path[1:], value)
		if err != nil {
			return nil, err
		}
		obj[e.key] = child
		return obj, nil
	}
}

// unwrapRoot removes the conventional "json" wrapper from the merged tree.
func unwrapRoot(tree interface{}) interface{} {
	if m, ok := tree.(map[string]interface{}); ok && len(m) == 1 {
		if v, ok := m["json"]; ok {
			return v
		}
	}
	return tree
}
'''.lstrip('\n')
open('statements.go','w').write(content)
