	for i, e := range path {
		if i > 0 && e.kind == elemBareKey {
			sb.WriteString(".")
		}
		sb.WriteString(e.raw)
	}
	return sb.String()
}

// parseValue parses the value part of a statement which starts at index i.
func parseValue(line string, i int, path []pathElement, rawPath string) (*statement, error) {
	j := i
	for j < len(line) && isSpaceByte(line[j]) {
		j++
	}
	if j >= len(line) {
		return &statement{path: path, raw: rawPath, hasEq: true}, errNoValue
	}
	c := line[j]
	switch {
	case c == '"':
		k := scanQuoted(line, j)
		if k < 0 {
			k = len(line)
		}
		value := line[j:k]
		m := k
		for m < len(line) && isSpaceByte(line[m]) {
			m++
		}
		if m >= len(line) || line[m] != ';' {
			return &statement{path: path, raw: rawPath, value: value, hasEq: true}, errNoValue
		}
		return &statement{path: path, raw: rawPath, value: value, hasEq: true}, nil
	case c == '{' || c == '[':
		closing := byte('}')
		if c == '[' {
			closing = ']'
		}
		if j+1 < len(line) && line[j+1] == closing {
			value := line[j : j+2]
			m := j + 2
			for m < len(line) && isSpaceByte(line[m]) {
				m++
			}
			if m >= len(line) || line[m] != ';' {
				return &statement{path: path, raw: rawPath, value: value, hasEq: true}, errNoValue
			}
			return &statement{path: path, raw: rawPath, value: value, hasEq: true}, nil
		}
		m := j + 1
		for m < len(line) && isSpaceByte(line[m]) {
			m++
		}
		if m < len(line) && line[m] == ';' {
			value := strings.TrimSpace(line[j:m]) + ";"
			st := &statement{path: path, raw: rawPath, value: value, hasEq: true}
			return st, fmt.Errorf("invalid value `%s`", strings.TrimSuffix(value, ";"))
		}
		return &statement{path: path, raw: rawPath, value: line[j : j+1], hasEq: true}, errNoValue
	}
	k := strings.IndexByte(line[j:], ';')
	if k < 0 {
		return &statement{path: path, raw: rawPath, value: line[j:], hasEq: true}, errNoValue
	}
	value := line[j : j+k+1]
	st := &statement{path: path, raw: rawPath, value: value, hasEq: true}
	var v interface{}
	d := json.NewDecoder(strings.NewReader(value))
	d.UseNumber()
	if err := d.Decode(&v); err != nil {
		return st, fmt.Errorf("invalid value `%s`", strings.TrimSuffix(value, ";"))
	}
	return st, nil
}

// ungronStatements reads gron statements from r, one per line.
func ungronStatements(in io.Reader) (statements, error) {
	var sts statements
	scanner := bufio.NewScanner(in)
	scanner.Buffer(make([]byte, 0, 1024*1024), 1024*1024)
	for scanner.Scan() {
		st, err := parseStatement(scanner.Text())
		if st != nil {
			if err != nil {
				return nil, &statementError{st: st, err: err}
			}
			sts = append(sts, st)
			continue
		}
		if err != nil {
			continue
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, errors.New(err.Error())
	}
	return sts, nil
}
