func gronMode(in io.Reader, opts *options, colourise bool) int {
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()

	if opts.stream {
		if err := gronStream(in, w, opts, colourise); err != nil {
			fmt.Fprintln(os.Stderr, err)
