// assignLeaf stores value at an existing position, rejecting attempts to
// replace one kind of container with another.
func assignLeaf(existing, value interface{}) (interface{}, error) {
	switch existing.(type) {
	case map[string]interface{}:
		if _, ok := value.(map[string]interface{}); !ok {
			return nil, errMergeObject
		}
	case []interface{}:
		if _, ok := value.([]interface{}); !ok {
			return nil, errMergeArray
		}
	}
	return value, nil
}

// mergeValue merges value into dst at the given path.
func mergeValue(dst interface{}, path []pathElement, value interface{}) (interface{}, error) {
	if len(path) == 0 {
		return assignLeaf(dst, value)
	}
	e := path[0]
	if e.kind == elemIndex {
		switch t := dst.(type) {
		case map[string]interface{}:
			return nil, errMergeObject
		case []interface{}:
			for len(t) <= e.index {
				t = append(t, nil)
			}
			child, err := mergeValue(t[e.index], path[1:], value)
			if err != nil {
				return nil, err
			}
			t[e.index] = child
			return t, nil
		default:
			arr := make([]interface{}, e.index+1)
			child, err := mergeValue(arr[e.index], path[1:], value)
			if err != nil {
				return nil, err
			}
			arr[e.index] = child
			return arr, nil
		}
	}
	switch t := dst.(type) {
	case []interface{}:
		return nil, errMergeArray
	case map[string]interface{}:
		child, err := mergeValue(t[e.key], path[1:], value)
		if err != nil {
			return nil, err
		}
		t[e.key] = child
		return t, nil
	default:
		obj := map[string]interface{}{}
		child, err := mergeValue(nil, path[1:], value)
		if err != nil {
			return nil, err
		}
		obj[e.key] = child
		return obj, nil
	}
}

