{"command": "cd /workspace/src && python3 - <<'PYEOF'
s=open('statements.go').read()
old_start = s.index('var (\n\terrMergeObject')
old_end = s.index('// unwrapRoot removes the conventional "json" wrapper')
new = r'''var (
	errMergeObject = errors.New("cannot merge object with non-object")
	errMergeArray  = errors.New("cannot merge array with non-array")
)

// mergeTrees merges two decoded JSON values.  Containers are merged
// recursively, scalars replace whatever was there before.
func mergeTrees(dst, value interface{}) (interface{}, error) {
	switch d := dst.(type) {
	case nil:
		return value, nil
	case map[string]interface{}:
		v, ok := value.(map[string]interface{})
		if !ok {
			return nil, errMergeObject
		}
		for k, e := range v {
			merged, err := mergeTrees(d[k], e)
			if err != nil {
				return nil, err
			}
			d[k] = merged
		}
		return d, nil
	case []interface{}:
		v, ok := value.([]interface{})
		if !ok {
			return nil, errMergeArray
		}
		for i, e := range v {
			for len(d) <= i {
				d = append(d, nil)
			}
			merged, err := mergeTrees(d[i], e)
			if err != nil {
				return nil, err
			}
			d[i] = merged
		}
		return d, nil
	default:
		return value, nil
	}
}

// mergeValue merges value into dst at the given path.
func mergeValue(dst interface{}, path []pathElement, value interface{}) (interface{}, error) {
	if len(path) == 0 {
		return mergeTrees(dst, value)
	}
	e := path[0]
	if e.kind == elemIndex {
		switch t := dst.(type) {
		case map[string]interface{}:
			return nil, errMergeObject
		case []interface{}:
			for len(t) <= e.index {
				t = append(t, nil)
			}
			child, err := mergeValue(t[e.index], path[1:], value)
			if err != nil {
				return nil, err
			}
			t[e.index] = child
			return t, nil
		default:
			arr := make([]interface{}, e.index+1)
			child, err := mergeValue(arr[e.index], path[1:], value)
			if err != nil {
				return nil, err
			}
			arr[e.index] = child
			return arr, nil
		}
	}
	switch t := dst.(type) {
	case []interface{}:
		return nil, errMergeArray
	case map[string]interface{}:
		child, err := mergeValue(t[e.key], path[1:], value)
		if err != nil {
			return nil, err
		}
		t[e.key] = child
		return t, nil
	default:
		obj := map[string]interface{}{}
		child, err := mergeValue(nil, path[1:], value)
		if err != nil {
			return nil, err
		}
		obj[e.key] = child
		return obj, nil
	}
}

'''
